"const { app, BrowserWindow } = require('electron');
const path = require('path');
const fs = require('fs');

app.disableHardwareAcceleration();
app.commandLine.appendSwitch('disable-gpu');
app.commandLine.appendSwitch('disable-gpu-compositing');
app.commandLine.appendSwitch('disable-software-rasterizer');
app.commandLine.appendSwitch('disable-http-cache');

const logFile = path.join(__dirname, 'diagnose_verify_erp.log');
function log(msg) {
  fs.appendFileSync(logFile, msg + '\n');
}

fs.writeFileSync(logFile, 'Verifying ERP direct startup...\n');

app.whenReady().then(async () => {
  const win = new BrowserWindow({
    width: 1280,
    height: 800,
    show: false,
    backgroundColor: '#09090b',
    webPreferences: {
      preload: path.join(__dirname, 'LEGENDS/electron/preload.cjs'),
      nodeIntegration: false,
      contextIsolation: true
    }
  });

  win.webContents.on('console-message', (e, level, message, line, sourceId) => {
    log(`[RENDERER CONSOLE ${level}] ${message} (${sourceId}:${line})`);
  });

  win.webContents.on('did-fail-load', (e, code, desc, url) => {
    log(`[DID-FAIL-LOAD] ${code}: ${desc} on ${url}`);
  });

  const indexPath = path.join(__dirname, 'LEGENDS/release/FITNESS_LEGENDS_TERMINAL-win32-x64/resources/app/dist/index.html');
  await win.loadFile(indexPath, { query: { mode: 'main' } });

  setTimeout(async () => {
    try {
      const pageText = await win.webContents.executeJavaScript('document.body.innerText');
      log('Page text: ' + pageText.substring(0, 400).replace(/\n/g, ' '));
      const image = await win.capturePage();
      fs.writeFileSync(path.join(__dirname, 'diagnose_erp_verified.png'), image.toPNG());
      log('Captured screen: ' + image.getSize().width + 'x' + image.getSize().height);
    } catch (err) {
      log('Error: ' + err.message);
    }
    app.quit();
  }, 3500);
});
"

