"const { app, BrowserWindow } = require('electron');
const path = require('path');
const fs = require('fs');

app.disableHardwareAcceleration();
app.commandLine.appendSwitch('disable-http-cache');

const logFile = path.join(__dirname, 'test_render_clean.log');
function log(msg) { fs.appendFileSync(logFile, msg + '\n'); }
fs.writeFileSync(logFile, 'Testing clean render...\n');

app.whenReady().then(async () => {
  const win = new BrowserWindow({
    width: 1280,
    height: 800,
    show: false,
    backgroundColor: '#09090b',
    webPreferences: {
      preload: path.join(__dirname, 'electron/preload.cjs'),
      nodeIntegration: false,
      contextIsolation: true,
      webSecurity: false
    }
  });

  win.webContents.on('console-message', (e, level, message, line, sourceId) => {
    log(`[CONSOLE ${level}] ${message} (${sourceId}:${line})`);
  });

  win.webContents.on('did-fail-load', (e, code, desc, url) => {
    log(`[DID-FAIL-LOAD] ${code}: ${desc} on ${url}`);
  });

  const indexPath = path.join(__dirname, 'release/FITNESS_LEGENDS_TERMINAL-win32-x64/resources/app/dist/index.html');
  log('Loading: ' + indexPath);
  await win.loadFile(indexPath, { query: { mode: 'main' } });

  setTimeout(async () => {
    const rootLen = await win.webContents.executeJavaScript('document.getElementById("root") ? document.getElementById("root").innerHTML.length : -1');
    log('Root innerHTML length: ' + rootLen);
    const bodyText = await win.webContents.executeJavaScript('document.body.innerText.substring(0, 300)');
    log('Body text:\n' + bodyText);
    const image = await win.capturePage();
    fs.writeFileSync(path.join(__dirname, 'test_clean_screenshot.png'), image.toPNG());
    log('Screenshot captured, size: ' + image.getSize().width + 'x' + image.getSize().height);
    app.quit();
  }, 3000);
});
"

