"const { app, BrowserWindow } = require('electron');
const path = require('path');
const fs = require('fs');

const mode = process.argv.includes('--terminal') ? 'terminal' : 'main';
console.log('Testing mode:', mode);

app.disableHardwareAcceleration();
app.commandLine.appendSwitch('disable-http-cache');

app.whenReady().then(async () => {
  const win = new BrowserWindow({
    width: 1280,
    height: 800,
    show: false,
    backgroundColor: '#09090b',
    webPreferences: {
      preload: path.join(__dirname, 'electron/preload.cjs'),
      nodeIntegration: false,
      contextIsolation: true,
      webSecurity: false,
      allowRunningInsecureContent: true
    }
  });

  const indexPath = path.join(__dirname, 'dist/index.html');
  console.log('Loading:', indexPath);
  await win.loadFile(indexPath, { query: { mode } });

  setTimeout(async () => {
    try {
      const rootLength = await win.webContents.executeJavaScript('document.getElementById("root").innerHTML.length');
      console.log('Mode ' + mode + ' root innerHTML length: ' + rootLength);
      const img = await win.capturePage();
      const outImg = path.join(__dirname, '../../test_' + mode + '_screen.png');
      fs.writeFileSync(outImg, img.toPNG());
      console.log('Saved image to ' + outImg);
    } catch (e) {
      console.error(e);
    }
    app.quit();
  }, 2500);
});
"
